def semver_sort(versions):
    def parse_version(version):
        # Split build metadata
        if '+' in version:
            version, build = version.split('+', 1)
        else:
            build = ''

        # Split pre-release
        if '-' in version:
            base, prerelease = version.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            base = version
            prerelease_parts = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        return (major, minor, patch, prerelease_parts)

    def prerelease_key(prerelease_parts):
        # If no pre-release, it sorts after any pre-release
        if prerelease_parts is None:
            return (1,)  # Sorts after (0, ...)

        # Convert pre-release identifiers for comparison
        key = [0]  # Mark as having pre-release
        for part in prerelease_parts:
            if part.isdigit():
                # All-digit identifiers: compare numerically and sort before non-digit
                key.append((0, int(part)))
            else:
                # Non-digit identifiers: compare by ASCII
                key.append((1, part))
        return tuple(key)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease_parts = parse_version(version)
        return (major, minor, patch, prerelease_key(prerelease_parts), index)

    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [version for _, version in sorted_versions]

